<script>
(()=>{let lines=@json(old('lines',$document?->lines ?? []));const box=document.getElementById('quote-lines');
function render(){box.replaceChildren();lines.forEach((line,i)=>{const row=document.createElement('div');row.className='item-row';const name=document.createElement('div');name.textContent=line.name?line.name+' — '+(line.unit_name||''):line.label||'สินค้าที่เลือก #'+line.unit_quantity_id;row.append(name);const id=document.createElement('input');id.type='hidden';id.name=`lines[${i}][unit_quantity_id]`;id.value=line.unit_quantity_id;row.append(id);[['quantity','จำนวน','0.00001'],['unit_price','ราคาต่อหน่วย (บาท)','0.01']].forEach(([key,label,step])=>{const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.type='number';input.step=step;input.min=step;input.required=true;input.name=`lines[${i}][${key}]`;input.value=line[key];input.oninput=()=>line[key]=input.value;l.append(input);row.append(l)});const remove=document.createElement('button');remove.type='button';remove.textContent='ลบ';remove.onclick=()=>{lines.splice(i,1);render()};row.append(remove);box.append(row)})}
async function search(type){const text=document.getElementById(type+'-search').value.trim(),out=document.getElementById(type+'-results'),message=document.getElementById('search-message');out.replaceChildren();if(text.length<2){message.textContent='กรอกอย่างน้อย 2 ตัวอักษร';return}message.textContent='กำลังค้นหา…';try{const url=new URL(@json(route('ns.sales.lookup')),location.origin);url.search=new URLSearchParams({branch_id:@json($branch),type,search:text});const res=await fetch(url,{headers:{Accept:'application/json'}});if(!res.ok)throw Error();const rows=await res.json();message.textContent=rows.length?'เลือกรายการที่ต้องการ':'ไม่พบรายการ';rows.forEach(item=>{const b=document.createElement('button');b.type='button';b.textContent=item.label;b.onclick=()=>{if(type==='customer'){document.getElementById('customer-id').value=item.id;document.getElementById('customer-label').textContent=item.label}else if(!lines.some(l=>Number(l.unit_quantity_id)===item.id)){lines.push({unit_quantity_id:item.id,label:item.label,quantity:1,unit_price:item.price});render()}else{message.textContent='มีสินค้าหน่วยนี้แล้ว กรุณาแก้จำนวนในรายการเดิม'}out.replaceChildren()};out.append(b)})}catch{message.textContent='ค้นหาไม่สำเร็จ กรุณาลองใหม่ หรือเข้าสู่ระบบใหม่'}}
['customer','product'].forEach(t=>{document.getElementById('find-'+t).onclick=()=>search(t);document.getElementById(t+'-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search(t)}}});render();document.getElementById('quote-editor').onsubmit=e=>{if(!lines.length||!document.getElementById('customer-id').value){e.preventDefault();document.getElementById('search-message').textContent='เลือกลูกค้าและสินค้าอย่างน้อย 1 รายการก่อนบันทึก'}};
})();</script>
